#!/usr/bin/env bash
# build-linux-binaries.sh - builds static x86-64 Linux binaries of the three
# compilers into server/bin/linux/ for the Vercel deployment.
#
#   bash scripts/build-linux-binaries.sh      (run on Linux or in WSL)
#
# Needs gcc, g++, flex, bison and make:  sudo apt install build-essential flex bison
# The files in server/bin/linux/ are GENERATED by this script; rerun it after
# changing any compiler, then commit the new binaries.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/server/bin/linux"
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK:?}"' EXIT

# Build from a clean copy so the Windows build/ folders are left alone.
cp -r "$ROOT/backend/c-compiler" "$ROOT/backend/c++_compiler" "$ROOT/backend/javacompiler" "$WORK/"
rm -rf "${WORK:?}"/*/build
# Sources checked out on Windows may have CRLF line endings.
find "$WORK" -type f \( -name '*.l' -o -name '*.y' -o -name '*.c' -o -name '*.cpp' \
    -o -name '*.h' -o -name '*.hpp' -o -name 'Makefile' \) -exec sed -i 's/\r$//' {} +

make -C "$WORK/c-compiler"   OS=Linux CC="gcc -static"
make -C "$WORK/c++_compiler" OS=Linux CXX="g++ -static"
make -C "$WORK/javacompiler" OS=Linux CXX="g++ -static"

mkdir -p "$OUT"
install -m 755 "$WORK/c-compiler/build/tricora"      "$OUT/tricora"
install -m 755 "$WORK/c++_compiler/build/compiler.exe" "$OUT/compiler"   # this Makefile always names it .exe
install -m 755 "$WORK/javacompiler/build/minijavac"  "$OUT/minijavac"
strip "$OUT"/tricora "$OUT"/compiler "$OUT"/minijavac

ls -l "$OUT"
